import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { MySchoolsPage } from './my-schools.page';

const routes: Routes = [
  {
    path: '',
    component: MySchoolsPage
  },
  {
    path: 'pums-session-details',
    loadChildren: () => import('./pums-session-details/pums-session-details.module').then( m => m.PumsSessionDetailsPageModule)
  },
  {
    path: 'otp-submission',
    loadChildren: () => import('./otp-submission/otp-submission.module').then( m => m.OtpSubmissionPageModule)
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class MySchoolsPageRoutingModule {}
