import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { UserSessionService } from 'src/app/services/usersession.service';
import { EmisService } from "src/app/services/emis/emis.service";
import { UserService } from 'src/app/services/emis/user.service';

@Component({
  selector: 'app-my-schools',
  templateUrl: './my-schools.page.html',
  styleUrls: ['./my-schools.page.scss'],
})
export class MySchoolsPage implements OnInit {
  infoSchHide: boolean;
  showtable:boolean=false;
  emis_usertype:any;
  emisName: any;
  type: number;
  schoolList: any;
  teacher_id: any;
  block: any;
  schoolListAll: any[];
  indexVal: any;
  dataSchoolId: any;
  batchGrpList: any[];
  batchList: any[];
  allowGroup: boolean = false;
  databatchGrpList: any[];
  day: number;
  curr_month: number;
  week: number;

  constructor(private router: Router,private userSessionService: UserSessionService,private emisService: EmisService,
    private userService: UserService) {
    this.emis_usertype = this.userSessionService.emis_usertype()
    this.emisName = this.userSessionService.emis_username()
    this.teacher_id = this.userSessionService.teacher_id();

    let currentDate = new Date();
    this.day = currentDate.getDay()
    var date = currentDate.getDate();
    this.curr_month = currentDate.getMonth() +1;
    // var weekOfMonth = Math.ceil((date - 1 - this.day) / 7);
    var weekOfMonth = (0 | currentDate.getDate() / 7)+1;
    this.week = weekOfMonth
   }

  ngOnInit() {
    if(this.emis_usertype == '39'){
      this.userService.getOoscUserDetails(this.teacher_id).subscribe(res => { 
        if (res.dataStatus) {
          this.block = res.result[0].block_id;
          if(this.block){
            this.initialGet()
          }
        }
      })
    }
  }

  initialGet(){
    let data = {
      "BlkId": this.block
    }

    this.schoolListAll = [];
    this.emisService.ArpSchlListBrte(data).subscribe(res => {
      if(res.dataStatus){
        this.schoolListAll = res.result;
      }
    });
  }

  ionViewDidEnter() {
    // if(this.emis_usertype == '55'){
    //   this.type = 1
    // }
    // else{
    //   this.type = 2
    // }
    if(this.emis_usertype == '55'){
      let data = {
        "arpId": this.emisName
      }
  
      this.schoolList = [];
      this.emisService.ArpSchlDetails(data).subscribe(res => {
        this.schoolList = res.result
      });
    }

    if(this.emis_usertype == '39'){
      this.userService.getOoscUserDetails(this.teacher_id).subscribe(res => { 
        if (res.dataStatus) {
          this.block = res.result[0].block_id;
          if(this.block){
            this.initialGet()
          }
        }
      })
    }
    
  }
  SchInfo(){

    this.infoSchHide = true

  }

  SchInfohide(i,data){
      this.allowGroup = false
      this.indexVal = i
      this.dataSchoolId = data.school_id
      

      this.batchGrpList = [];
      this.emisService.ArpBtchGropBrte(this.dataSchoolId).subscribe(res => {
        if(res.dataStatus){
          this.batchGrpList = res.result;
          this.showtable = true;

          if(this.batchGrpList){
            this.batchList = []
            for(let i=0;i<this.batchGrpList.length;i++){

              if (this.batchList.indexOf(this.batchGrpList[i].batch_id) === -1) {
                this.batchList.push(this.batchGrpList[i].batch_id);
              }
             
            }
          }
        }
        
      });
  }

  groupDiv(val){
    this.databatchGrpList = []
    for(let i=0;i<this.batchGrpList.length;i++){

      if (val == this.batchGrpList[i].batch_id) {
        this.databatchGrpList.push(this.batchGrpList[i]);
      }
     
    }
    this.allowGroup = true;

  }
  showlow(){
    this.showtable = false;
  }
  showlow1(){
    this.allowGroup = false
  }
  pums_session_details(val){
    this.router.navigate(["/tabs/pums-session-details"],{ queryParams: { 'schoolId': val.school_id}})
  }
 
  nextpage(val,data){
    this.router.navigate(["/tabs/session-details"],{ queryParams: {'groupData': JSON.stringify(val),'schoolData':JSON.stringify(data)}}) 
  }
  backBtn(){
    this.router.navigate(["/tabs/art-culture"]) 
  }
}
